import { TagCloud } from "@rhs-ui/primitives/tag-cloud";

export default function Demo(): React.JSX.Element {
  const tags = [["Planning", 42], ["Pricing", 24], ["Remote work", 31], ["Hiring", 9], ["Design", 18], ["Engineering", 27], ["Meetings", 14], ["Culture", 21], ["Tools", 6], ["Leadership", 11], ["Onboarding", 4], ["Writing", 16]] as const;
  return (
    <div className="mx-auto max-w-md p-8">
      <TagCloud showCounts tags={tags.map(([label, count]) => ({ label, count, href: `#${label.toLowerCase().replace(" ", "-")}` }))} />
    </div>
  );
}
